#!/usr/bin/env bash
# Concept sheets for every weapon (image model, reference-guided by Moxie's sheets).
#   bash art/weapons/concepts.sh [id ...]      (no ids = all that are missing; FORCE=1 regenerates)
# Output: docs/reference/generated/weapons/<id>.png
cd "$(dirname "$0")/../.." || exit 1
OUT=docs/reference/generated/weapons
STYLE="Game prop concept model sheet, clean cel-shaded anime style with bold black ink outlines and flat colours, on a plain dark charcoal background. Layout: large orthographic SIDE view on the left, orthographic TOP view below it, a THREE-QUARTER view in the centre, and on the right the same girl from the reference images (Moxie: scrappy streetwear tech scavenger, messy brown pigtails, yellow star headphones, yellow bomber jacket, black cargo pants) holding or wearing it to show scale. The object is improvised by her from scavenged cassette-era audio hardware: chunky readable shapes, real separate parts, bolts, tape wraps, stickers, cables, signature yellow accents, small cyan or magenta glowing parts. Strong unique silhouette that reads at thumbnail size. No text labels except small sticker graphics."
declare -A P
P[splice_blade]="SPLICE BLADE: a tape-splicing knife that grew into a short broad single-edged sword, about half her height. Crossguard is an aluminium tape splicing block with a tape channel and angled cut slots; wide off-white steel blade with a diagonal 45-degree splice-cut tip, a dark fuller channel with a thin cyan glowing line like a strip of tape, yellow painted spine; grip wrapped in black gaffer tape; pommel is a small cassette tape hub. Balanced, medium weight."
P[stylus_shiv]="STYLUS SHIV: a very light short dagger made from a record-player tone arm, forearm length. A thin chrome arm tube ends in a boxy phono cartridge headshell with a curved finger-lift hook; from the cartridge a long filed stylus needle spike juts forward as the stabbing point with a tiny magenta glowing diamond tip; cylindrical counterweight with dial marks as the pommel; thin coloured cartridge wires. Fast, thin, precise, small."
P[amp_sledge]="AMP SLEDGE: a huge heavy two-handed sledgehammer whose head is a boxy guitar amplifier head (yellow tolex covering, black grille cloth front, metal corner protectors, a row of knobs, carry handle on top, glowing orange vacuum tubes visible at the back) clamped with scaffold couplers onto a steel scaffold pole about three quarters of her height; a coiled guitar cable wraps the pole; grip tape at the bottom. Massive, slow, crushing, top-heavy silhouette."
P[reel_lash]="REEL LASH: a very long thin whip made of steel-cored brown magnetic tape that feeds out of an open metal tape reel (three windows, wound tape visible) mounted on a hand grip with a small crank handle and a guide eyelet; the tape ribbon whip is longer than she is tall, drawn in a long graceful S curve, ending in a small weighted steel leader clip with a cyan glow. Extremely long and narrow silhouette, tiny handle."
P[speaker_knuckles]="SPEAKER KNUCKLES: a pair of fingerless-glove gauntlets, left and right, each with a hot-pink tweeter speaker cone riveted over the knuckles in a chunky metal knuckle-duster frame, magnet and voice coil behind, short speaker wire to a wrist strap with a small jack plug, shock rings. Show both gauntlets, front of the fist view, side view and top view. Compact, punchy, round cone silhouette on the fist."
P[vinyl_glaive]="VINYL GLAIVE: a long polearm taller than her: a sharpened black twelve-inch vinyl record with a chrome-ground cutting rim and a yellow centre label, mounted flat like a circular glaive blade at the end of a wooden broom handle by a turntable spindle bracket and a 45 adapter, with tape wraps on the shaft and a rubber broom-end cap; the record can spin. Long shaft with a big disc at the top: lollipop silhouette, sweeping weapon."
P[mixtape_rocket]="MIXTAPE ROCKET gadget for a cartoon video game: a chunky cassette-deck gadget worn on top of the LEFT forearm on a wrist bracer: an open cassette deck door / tape well that holds one fat toy bottle-rocket built from a cassette shell with small fins and a red nose cone, loaded and visible; short guide rail, a little chip with a tiny screen, coral red (#ff4d6d) body with yellow stickers. Also show the toy rocket alone: a cassette tape body with a bottle-rocket nozzle and fins. Short, boxy, heavy silhouette."
P[needle_rail]="NEEDLE RAIL: a long slim railgun worn on top of the LEFT forearm on a wrist bracer: two parallel thin silver rails extending past the hand, copper magnet coils from a tape head around the breech, a little rotary magazine of phonograph needles, cyan glow between the rails. Also show the projectile alone: a long thin phonograph needle lance. Very long, very thin, precise silhouette."
P[bleed_emitter]="BLEEDTHROUGH EMITTER: a strange emitter worn on top of the LEFT forearm on a wrist bracer: two tape heads (A-side and B-side) facing each other across a gap, feeding a short flared horn made of concentric floating purple rings (#8a5cff), with a small spinning tape loop; ghostly violet glow. Also show the projectile alone: a soft ghostly violet orb with echo rings that phases through walls. Round, ringed, eerie silhouette."
P[bass_drop]="BASS DROP MORTAR: a stubby wide mortar tube worn on top of the LEFT forearm on a wrist bracer, tilted upward at 45 degrees: a fat tube with a subwoofer speaker cone as the breech at the back, bipod strut, green (#7dff6b) glowing level meter, carry strap. Also show the projectile alone: a squat bass canister shell like a small subwoofer drum with a green glowing ring. Fat, short, upward-pointing silhouette."
P[static_spray]="STATIC SPRAY: a shorted-out mini boombox worn on top of the LEFT forearm on a wrist bracer, firing forward: boombox body with two round speakers, a crank handle on the side, bent antenna, and a wide flared fan-shaped nozzle at the front with five spark emitters, cyan (#3ec5ff) electric sparks. Also show the projectile alone: a small jagged cyan spark pellet. Wide, short, fan-fronted silhouette."
ids=("$@"); [ ${#ids[@]} -eq 0 ] && ids=(splice_blade stylus_shiv amp_sledge reel_lash speaker_knuckles vinyl_glaive mixtape_rocket needle_rail bleed_emitter bass_drop static_spray)
one() { id="$1"; f="$OUT/$id.png"; [ -f "$f" ] && [ -z "${FORCE:-}" ] && return 0
  IMG_SIZE=1536x1024 IMG_QUALITY=${IMG_QUALITY:-medium} bash tools/img edit "$f" "$STYLE ${P[$id]}" docs/reference/R01-moxie-concept.png docs/reference/R02-moxie-details.png || echo "FAILED $id"; }
i=0
for id in "${ids[@]}"; do one "$id" & i=$((i+1)); if [ $((i%2)) -eq 0 ]; then wait; fi; done; wait
